theorem tendsto_norm_cofinite_iff_finite (x : ∀ i, E i) :
    Tendsto (fun i => ‖x i‖) cofinite (𝓝 0) ↔
      ∀ ε : ℝ, 0 < ε → Set.Finite {i | ε ≤ ‖x i‖}
